import {partitionSize,partitionRect,containsRect} from './site.js';
import {createGame,tick,act,serializeGame,deserializeGame,getGuildStats,getMemberStats,previewMission,getAvailableQuests,getAvailableRecruits,getUpgradeCost,getExpansionCost,getBuildingExpansionCost,getRoomSize,getPartitionCost,DAY_LENGTH,introActive,normalizeProfile,PROFILE_LOOKS,DEFAULT_PROFILE} from './game.js';
import {FACILITIES,MEMBERS,QUESTS,EQUIPMENT,JOBS,RANKS,REGIONS,GUILD_EVENTS,MISSION_POLICIES,RANK_REQUIREMENTS,ROOM_TYPES,BUILDING_STAGES} from './content.js';
import {drawPortrait,drawItemIcon,drawBattleScene,drawQuestArt} from './render.js';
import {GuildRenderer} from './world.js';
import {drawDungeonScene,missionStage,buildDungeon} from './dungeon.js';
import {makeRoom,gridPoint} from './guild-art.js';
const $=id=>document.getElementById(id);
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=value=>Math.round(Number(value)||0).toLocaleString('th-TH');
const saveKey='little-leaf-guild:v1';
const backupKey=saveKey+':backup';
let state,saveFailure='',loadNotice='';
let hasSave=false;try{const stored=localStorage.getItem(saveKey);hasSave=!!stored;state=stored?deserializeGame(stored):createGame(Date.now()%100000+1,{opening:true});}catch(error){try{const backup=localStorage.getItem(backupKey);state=backup?deserializeGame(backup):createGame();loadNotice=backup?'กู้ข้อมูลจากบันทึกสำรองแล้ว':'ไฟล์บันทึกเดิมอ่านไม่ได้ เริ่มกิลด์ใหม่ให้แล้ว ข้อมูลเดิมยังอยู่ในบันทึกสำรอง';}catch{state=createGame();loadNotice='อ่านบันทึกไม่ได้ เริ่มกิลด์ใหม่ให้แล้ว';}}
state.settings??={};
// UI preferences stay local; simulation pause is driven below.
state.settings.paused=false;
let ui={tab:'home',questId:null,memberId:null,facilityId:null,missionId:null,region:'meadow',selected:new Set(),policy:'balanced',buildType:null,moveId:null,roomPlacement:null,moveRoomId:null,partitionId:null,roomWidth:3,roomHeight:3,zoom:1,paused:false,speed:state.settings.speed||1,sound:!!state.settings.sound,tutorial:!state.completedQuests?.patrol};
let renderer;
try{renderer=new GuildRenderer($('guild-world'),onSceneSelect);renderer.setState(state);}catch(error){console.error(error);window.guildBoot?.fail(error);}
let audioContext;
function playChime(){if(!ui.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const now=audioContext.currentTime;for(const [i,f] of [523.25,659.25,783.99].entries()){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(0,now+i*.065);gain.gain.linearRampToValueAtTime(.035,now+i*.065+.012);gain.gain.exponentialRampToValueAtTime(.001,now+i*.065+.23);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.065);osc.stop(now+i*.065+.24);}}catch{}}
function toast(text,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':' success');node.textContent=text;$('toasts').appendChild(node);setTimeout(()=>node.remove(),5500);while($('toasts').children.length>3)$('toasts').firstChild.remove();}
function save(manual=false){try{const data=serializeGame(state);const previous=localStorage.getItem(saveKey);if(previous){try{deserializeGame(previous);localStorage.setItem(backupKey,previous);}catch{localStorage.setItem(saveKey+':corrupt',previous);}}localStorage.setItem(saveKey,data);saveFailure='';$('save-status').textContent='บันทึกแล้ว · '+new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});if(manual)toast('บันทึกกิลด์เรียบร้อย');return true;}catch(error){saveFailure='บันทึกอัตโนมัติไม่ได้ กรุณาส่งออกไฟล์เซฟ';$('save-status').textContent='⚠ '+saveFailure;if(manual)toast(saveFailure,true);return false;}}
function dispatch(type,payload={}){try{const result=act(state,type,payload);if(!result.ok){toast(result.message||'ยังทำรายการนี้ไม่ได้',true);return false;}toast(result.message||'เรียบร้อย');playChime();renderer?.setState(state);save();syncUI();return true;}catch(error){console.error(error);toast('ทำรายการไม่สำเร็จ ข้อมูลกิลด์ยังอยู่',true);return false;}}
function activeMissions(){return state.missions.filter(m=>m.status==='active'||m.status==='decision');}
function isAway(id){return activeMissions().some(m=>m.memberIds.includes(id));}
function baseJob(id){const j=JOBS[id];return j?.parent||id;}
function jobName(id){return JOBS[id]?.name||id;}
function roleName(id){return({tank:'ป้องกัน',scout:'สำรวจ',magic:'เวท',heal:'รักษา',damage:'โจมตี',support:'สนับสนุน'})[id]||id;}
function moneyCost(cost={}){return Object.entries(cost).filter(([,v])=>v>0).map(([k,v])=>`${({gold:'G',wood:'ไม้',stone:'หิน',herb:'สมุนไพร'})[k]||k} ${n(v)}`).join(' · ')||'ไม่ใช้เสบียง';}
function canAfford(cost={}){return Object.entries(cost).every(([k,v])=>(state[k]||0)>=v);}
function rankEnough(rank){return RANKS.indexOf(state.rank)>=RANKS.indexOf(rank||'F');}
function inventoryCount(id){const inv=state.inventory||{};if(Array.isArray(inv))return inv.filter(x=>(typeof x==='string'?x:x.equipmentId||x.id)===id).length;return Number(inv[id]||0);}
function item(id){return EQUIPMENT.find(e=>e.id===id);}
function availableCount(id){return inventoryCount(id);}
function pct(value,max=100){return Math.max(0,Math.min(100,100*(Number(value)||0)/max));}
function portrait(member,extra=''){return `<canvas class="portrait" width="64" height="72" data-portrait="${h(member.id)}" ${extra}></canvas>`;}
function itemIcon(id){return `<canvas class="item-icon" width="40" height="40" data-item="${h(id)}"></canvas>`;}
function injectIcons(root=document){root.querySelectorAll('canvas[data-portrait]').forEach(c=>{const m=state.members.find(m=>m.id===c.dataset.portrait)||MEMBERS.find(m=>m.id===c.dataset.portrait);if(m)drawPortrait(c,m,64);});root.querySelectorAll('canvas[data-item]').forEach(c=>drawItemIcon(c,item(c.dataset.item)||c.dataset.item,40));root.querySelectorAll('canvas[data-furniture]').forEach(c=>drawFurniture(c,c.dataset.furniture));root.querySelectorAll('canvas[data-quest-art]').forEach(c=>drawQuestArt(c,QUESTS.find(q=>q.id===c.dataset.questArt)||{},{locked:'locked'in c.dataset}));root.querySelectorAll('canvas[data-region-art]').forEach(c=>drawQuestArt(c,{},{region:c.dataset.regionArt,locked:'locked'in c.dataset}));}
// Shop preview: the same isometric furniture sprites the scene uses, fitted into the card.
function drawFurniture(canvas,type){let parts;try{parts=makeRoom({id:'preview',type,x:0,y:0,rotation:0,level:1}).layers.map(part=>{const p=gridPoint(part.x,part.y);return{c:part.sprite.canvas,x:p.x-part.sprite.footX,y:p.y-part.sprite.footY,sort:p.y+part.sort};}).sort((a,b)=>a.sort-b.sort);}catch{return;}if(!parts.length)return;const minX=Math.min(...parts.map(p=>p.x)),minY=Math.min(...parts.map(p=>p.y)),maxX=Math.max(...parts.map(p=>p.x+p.c.width)),maxY=Math.max(...parts.map(p=>p.y+p.c.height));const ctx=canvas.getContext('2d'),w=canvas.width,hh=canvas.height,scale=Math.max(1,Math.min(4,Math.floor(Math.min((w-10)/(maxX-minX),(hh-10)/(maxY-minY)))));ctx.clearRect(0,0,w,hh);ctx.imageSmoothingEnabled=false;const ox=(w-(maxX-minX)*scale)/2,oy=(hh-(maxY-minY)*scale)/2;for(const p of parts)ctx.drawImage(p.c,Math.round(ox+(p.x-minX)*scale),Math.round(oy+(p.y-minY)*scale),Math.round(p.c.width*scale),Math.round(p.c.height*scale));}
function missionRatio(m){return Math.max(0,Math.min(1,(m.progress||0)/(m.duration||1)));}
function missionEventPending(m){return m.event&&!m.event.resolved;}
function taskText(m){if(isAway(m.id))return'ออกภารกิจ';if(m.injury>0)return'พักรักษา';return({rest:'พักฟื้น',train:'ฝึกฝน',work:'ช่วยงาน',auto:'เตรียมพร้อม'})[m.task]||'พักฟื้น';}
function syncHUD(){const stats=getGuildStats(state);$('resources').innerHTML=`<div class="resource"><span class="resource-icon">◈</span><div><small>เงินกิลด์</small><b>${n(state.gold)}</b></div></div><div class="resource"><span class="resource-icon wood">▰</span><div><small>ไม้</small><b>${n(state.wood)}</b></div></div><div class="resource"><span class="resource-icon stone">◆</span><div><small>หิน</small><b>${n(state.stone)}</b></div></div><div class="resource"><span class="resource-icon herb">❧</span><div><small>สมุนไพร</small><b>${n(state.herb)}</b></div></div><div class="resource rank"><span class="rank-seal">${h(state.rank)}</span><div><small>ชื่อเสียง</small><b>${n(state.rep)}</b></div></div>`;
const clock=Number(state.clock)||0;const minute=Math.floor(clock/DAY_LENGTH*1440);const hour=`${String(Math.floor(minute/60)%24).padStart(2,'0')}:${String(minute%60).padStart(2,'0')}`;$('calendar').innerHTML=`<strong>วันที่ ${n(state.day)}</strong><span>☀ ${hour}</span>`;
const chapter=state.story?.chapter||1;$('chapter-label').innerHTML=`<span>CHAPTER ${chapter}</span><b>${['','บ้านหลังเล็ก','เสียงระฆังในป่า','เส้นทางในหมอก','ทุกคนต้องกลับบ้าน','ใต้ร่มใบไม้'][chapter]||'ใต้ร่มใบไม้'}</b>`;
let objective,meta;if(state.story?.finished){objective='บ้านที่ทุกคนได้กลับมา';meta='แคมเปญสำเร็จ · สำรวจและพัฒนากิลด์ต่อได้';}else if(!state.completedQuests?.patrol){objective='ส่งทีมลาดตระเวนครั้งแรก';meta='เลือกคำร้อง → สมาชิก 3 คน → ส่งทีม';}else{objective=stats.nextRank?`เติบโตสู่กิลด์ระดับ ${stats.nextRank}`:'รักษาหัวใจป่า';const q=QUESTS.find(q=>q.id===stats.nextRankQuest);meta=stats.nextRank?`ชื่อเสียง ${n(state.rep)}/${n(stats.nextRankRep)}${q?' · '+q.name:''}`:'รับคำร้องสุดท้ายที่ป่าหมอกจันทร์';}$('objective').innerHTML=`<small>OUR NEXT LITTLE STEP</small><p>${h(objective)}</p><div class="objective-meta">${h(meta)}</div>`;
$('pause-button').textContent=ui.paused?'▶':'Ⅱ';$('pause-button').setAttribute('aria-label',ui.paused?'เดินเวลา':'หยุดเวลา');document.querySelectorAll('[data-speed]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.speed)===ui.speed&&!ui.paused);b.setAttribute('aria-pressed',String(Number(b.dataset.speed)===ui.speed&&!ui.paused));});
syncGoal();const missions=activeMissions();$('journeys-button').classList.toggle('nudge',!missions.length&&state.members.length>=3&&!state.story?.finished);$('journey-count').textContent=missions.length?String(missions.length):'';$('journey-count').classList.toggle('alert',missions.some(m=>missionEventPending(m)));syncBrand();const sheet=$('management-dialog').open,group=ui.tab==='journal'?'home':ui.tab;document.querySelectorAll('[data-dock]').forEach(b=>b.classList.toggle('active',sheet&&b.dataset.dock===group));let cards=missions.map(m=>{const q=QUESTS.find(q=>q.id===m.questId);return `<div class="journey-card ${missionEventPending(m)?'ready':''}" role="button" tabindex="0" data-open-mission="${h(m.id)}"><div class="journey-art">${m.memberIds.map(id=>state.members.find(x=>x.id===id)).filter(Boolean).map(m=>portrait(m)).join('')}</div><div class="journey-data"><b>${h(q?.name||m.questId)}</b><small>${missionEventPending(m)?'มีเหตุการณ์ · กดดูทีม':m.phase==='battle'?'กำลังต่อสู้ · กดดูทีม':`กำลังสำรวจ · ${Math.max(0,Math.ceil(m.duration-m.progress))} วินาที`}</small><div class="progress"><i style="width:${pct(missionRatio(m),1)}%"></i></div></div></div>`;});for(let i=missions.length;i<Math.min(2,stats.teamCap);i++)cards.push(`<div class="journey-card empty" role="button" tabindex="0" data-tab="quests">+ จัดทีมออกเดินทาง</div>`);if(stats.teamCap<2)cards.push('<div class="journey-card empty" data-tab="build" role="button" tabindex="0">วางโต๊ะวางแผนเพื่อเปิดทีมที่สอง</div>');$('mission-strip').innerHTML=cards.join('');injectIcons($('mission-strip'));
if(ui.buildType||ui.moveId||ui.roomPlacement||ui.moveRoomId){const room=ui.roomPlacement||state.rooms.find(r=>r.id===ui.moveRoomId);const label=room?ROOM_TYPES[room.type].name+' '+Object.values(partitionSize({...room,rotation:renderer?.rotation||0})).join('×'):ui.buildType?FACILITIES[ui.buildType]?.name:FACILITIES[state.facilities.find(f=>f.id===ui.moveId)?.type]?.name||'ของที่เลือก';$('build-hint').hidden=false;const title=`${ui.moveId||ui.moveRoomId?'ย้าย':'วาง'}${label}`;if($('pb-title').textContent!==title)$('pb-title').textContent=title;$('pb-confirm').textContent=ui.moveId||ui.moveRoomId?'ย้ายมาตรงนี้':'วางตรงนี้';document.body.classList.add('placing');}else{$('build-hint').hidden=true;document.body.classList.remove('placing');}
}
function syncUI(){syncHUD();document.querySelectorAll('.bottom-nav [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===ui.tab));const headings={home:profile().guildName,quests:'กระดานคำร้อง',members:'เหล่านักผจญภัย',build:'สร้างและตกแต่ง',workshop:'โต๊ะช่างและคราฟต์',journal:'สมุดบันทึกกิลด์'};$('panel-heading').textContent=headings[ui.tab];const scroller=$('panel-content');const top=scroller.scrollTop;const selectValues=new Map([...scroller.querySelectorAll('select[data-equip-select]')].map(e=>[e.dataset.equipSelect,e.value]));const next=({home:()=>guildTabs()+renderHome(),quests:renderQuests,members:renderMembers,build:renderBuild,workshop:renderWorkshop,journal:()=>guildTabs()+renderJournal()})[ui.tab]();const viewKey=[ui.tab,ui.questId,ui.missionId,ui.memberId,ui.facilityId,ui.partitionId].join('|'),moved=scroller.__key!==viewKey;scroller.__key=viewKey;const changed=scroller.__view!==next;if(changed){scroller.innerHTML=next;scroller.__view=next;}scroller.scrollTop=moved?0:top;scroller.querySelectorAll('select[data-equip-select]').forEach(e=>{const old=selectValues.get(e.dataset.equipSelect);if([...e.options].some(o=>o.value===old))e.value=old;});if(changed)injectIcons(scroller);drawMissionScene();}

function openMenu(){if(!$('management-dialog').open)$('management-dialog').show();document.body.classList.add('sheet-open');}
function closeMenu(){$('management-dialog').close();document.body.classList.remove('sheet-open');syncHUD();}
$('menu-button').addEventListener('click',()=>navigate('home'));
$('menu-close').addEventListener('click',closeMenu);
$('management-dialog').addEventListener('click',event=>{if(event.target===$('management-dialog')){const b=event.target.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)closeMenu();}});
function renderHome(){const stats=getGuildStats(state);return `<div class="home-intro"><small>${state.profile?'หัวหน้ากิลด์ '+h(profile().masterName):'บ้านของเหล่านักผจญภัย'}</small><h2>${h(profile().guildName)}</h2><p>ระดับ ${h(state.rank)} · วันที่ ${n(state.day)} · สมาชิก ${stats.memberCount}/${stats.memberCap} คน</p></div><div class="home-resources">${[['gold','เงินกิลด์','G'],['wood','ไม้',''],['stone','หิน',''],['herb','สมุนไพร','']].map(([key,label,unit])=>`<div><small>${label}</small><b>${n(state[key])} ${unit}</b></div>`).join('')}</div><div class="home-objective">${$('objective').innerHTML}</div><div class="menu-grid">${[['quests','▤','กระดานคำร้อง','จัดทีมและออกสำรวจ'],['members','♟','นักผจญภัย','พัก ฝึก และรับสมาชิก'],['build','▧','ห้องและต่อเติม','วาง ย้าย หมุน และต่อเติม'],['workshop','⚒','โรงคราฟต์','เตรียมอาวุธและอุปกรณ์'],['journal','✦','สมุดกิลด์','เรื่องราว บัญชี และกิจกรรม']].map(([tab,icon,title,copy])=>`<button data-tab="${tab}"><span>${icon}</span><b>${title}</b><small>${copy}</small></button>`).join('')}</div>`;}

function questStars(q){const max=Math.max(...QUESTS.map(x=>x.difficulty));return Math.max(1,Math.min(5,Math.round(q.difficulty/max*5)));}
function starLine(q){const k=questStars(q);return '<span class="qstars" aria-label="ความยาก '+k+' ดาว">'+'★'.repeat(k)+'<i>'+'★'.repeat(5-k)+'</i></span>';}
function rewardChips(reward={},extra=''){return `<div class="qrewards ${extra}">${[['gold','◈','G'],['wood','▰',''],['stone','◆',''],['herb','❧',''],['rep','★','']].filter(([k])=>reward[k]>0).map(([k,icon,unit])=>`<span class="qr-${k}"><i>${icon}</i>${n(reward[k])}${unit?' '+unit:''}</span>`).join('')}</div>`;}
function renderQuests(){if(ui.missionId)return renderMission();if(ui.questId)return renderQuestDetail();const quests=getAvailableQuests(state),missions=activeMissions();
 const tabs=`<div class="map-tabs">${REGIONS.map(r=>{const list=quests.filter(q=>q.region===r.id),open=list.some(q=>!q.locked),fresh=list.filter(q=>!q.locked&&!q.completed).length;return `<button data-region="${r.id}" class="${ui.region===r.id?'active':''}"><canvas width="96" height="54" data-region-art="${r.id}" ${open?'':'data-locked'}></canvas><b>${h(r.name)}</b><small>${open?(fresh?`ใหม่ ${fresh}`:`${list.filter(q=>!q.locked).length} คำร้อง`):'กิลด์ '+h(r.rank)}</small></button>`;}).join('')}</div>`;
 const cards=quests.filter(q=>q.region===ui.region).map(q=>{const badge=q.locked?'':q.final?'<span class="qbadge final">บทสุดท้าย</span>':!q.completed?'<span class="qbadge new">ใหม่!</span>':q.story?'<span class="qbadge">เรื่องราว</span>':`<span class="qbadge done">✓ ${q.completions}</span>`;
  return `<button class="qcard ${q.locked?'locked':''}" data-quest="${q.id}"><div class="qart"><canvas width="160" height="90" data-quest-art="${q.id}" ${q.locked?'data-locked':''}></canvas>${badge}</div><div class="qbody"><b>${h(q.name)}</b>${starLine(q)}<div class="qinfo"><span>◷ ${Math.ceil(q.duration/60)} นาที</span><span>${q.tags.map(roleName).join(' · ')}</span></div>${q.locked?`<small class="qlock">🔒 ${h(q.lockReason)}</small>`:rewardChips(q.reward)}</div></button>`;}).join('');
 return `${missions.length?'<div class="section-title">ทีมที่ออกเดินทาง</div><div class="menu-journeys">'+$('mission-strip').innerHTML+'</div>':''}${tabs}<div class="qgrid">${cards}</div>`;}

function renderQuestDetail(){const q=getAvailableQuests(state).find(q=>q.id===ui.questId);if(!q){ui.questId=null;return renderQuests();}const preview=previewMission(state,q.id,[...ui.selected],ui.policy);
 const chosen=[...ui.selected].map(id=>state.members.find(m=>m.id===id)).filter(Boolean),slots=[0,1,2].map(i=>{const m=chosen[i];return m?`<button class="slot filled" data-pick-member="${h(m.id)}" aria-label="เอา ${h(m.name)} ออก">${portrait(m)}<b>${h(m.name)}</b><small>${h(roleName(JOBS[m.class]?.role))} · Lv.${m.level}</small><i>✕</i></button>`:'<div class="slot empty"><span>+</span><small>เลือกสมาชิก</small></div>';}).join('');
 const roster=state.members.map(m=>{const busy=isAway(m.id)||m.injury>40,on=ui.selected.has(m.id);return `<button class="pick ${on?'on':''} ${busy?'busy':''}" data-pick-member="${h(m.id)}" aria-pressed="${on}" ${busy?'disabled':''}>${portrait(m)}<span><b>${h(m.name)}</b><small>${h(jobName(m.class))} · Lv.${m.level}</small><small class="${q.tags.includes(JOBS[m.class]?.role)?'fit':''}">${busy?(isAway(m.id)?'ออกภารกิจ':'ต้องรักษา'):q.tags.includes(JOBS[m.class]?.role)?'★ เหมาะกับงานนี้':roleName(JOBS[m.class]?.role)}</small><i class="mini-energy"><i style="width:${pct(m.energy)}%"></i></i></span></button>`;}).join('');
 const ratio=ui.selected.size?Math.min(1,(preview.readiness||0)/1.5):0,level=!ui.selected.size?'':preview.readiness>=.95?'good':preview.readiness>=.82?'ok':'bad';
 const policyNote={balanced:'เวลาและแรงปกติ',cautious:'ช้าลงแต่ปลอดภัยขึ้น',bold:'เร็วขึ้นแต่เหนื่อยและเสี่ยง'};
 return `<button class="back-button" data-back>‹ กระดานคำร้อง</button><div class="prep-hero"><canvas width="320" height="120" data-quest-art="${q.id}"></canvas><div class="prep-title"><small>${h(REGIONS.find(r=>r.id===q.region)?.name)}${q.story?' · เรื่องราว':''}</small><b>${h(q.name)}</b>${starLine(q)}</div></div><p class="detail-copy">${h(q.description)}</p>${rewardChips(q.reward,'big')}${q.locked?`<div class="readiness warn">${h(q.lockReason)}</div>`:''}
 <div class="section-title">ทีมเดินทาง<small>${ui.selected.size}/3 คน · งานนี้เหมาะกับ ${q.tags.map(roleName).join(' / ')}</small></div><div class="team-slots">${slots}</div><div class="roster">${roster}</div>
 <div class="section-title">แผนการเดินทาง</div><div class="plan-row">${Object.entries(MISSION_POLICIES).map(([id,p])=>`<button data-policy="${id}" class="${ui.policy===id?'active':''}"><b>${h(p.name)}</b><small>${h(policyNote[id]||'')}</small></button>`).join('')}</div>
 <div class="power-meter ${level}"><div class="pm-head"><b>${h(ui.selected.size?(preview.ok?preview.verdict:preview.reason||'ตรวจความพร้อมทีม'):'เลือกสมาชิกให้ครบ 3 คน')}</b><small>${ui.selected.size?`พลังทีม ${n(preview.power)} / ความยาก ${n(preview.difficulty)}`:''}</small></div><div class="pm-bar"><i style="width:${pct(ratio,1)}%"></i><span style="left:${pct(1/1.5,1)}%"></span></div><small>${preview.missingRoles?.length?'ขาดบทบาท: '+preview.missingRoles.map(roleName).join(' · ')+' · ':''}เวลา ${n(preview.duration||q.duration)} วินาที · เสบียง ${h(moneyCost(preview.cost||q.cost))}</small></div>
 <button class="primary go-button" data-send-mission ${!preview.ok||q.locked?'disabled':''}>ออกเดินทาง!</button>`;}

function renderMission(){const m=state.missions.find(m=>m.id===ui.missionId);if(!m){ui.missionId=null;return renderQuests();}const q=QUESTS.find(q=>q.id===m.questId);const ongoing=m.status==='active'||m.status==='decision';return `<button class="back-button" data-back>‹ กลับกระดานคำร้อง</button><div class="mission-head"><b>${h(q?.name||m.questId)}</b><small>${h(REGIONS.find(r=>r.id===q?.region)?.name||'')} · ${n(missionRatio(m)*100)}%</small></div><canvas id="mission-scene" class="dungeon-view" width="400" height="220"></canvas>${(()=>{if(!q)return'';const st=missionStage(m,buildDungeon(q)),done=!ongoing,at=done?4:st.back?4:st.fight>0?st.fight:st.target-.5;return `<div class="route">${['🏠','⚔','⚔','👑'].map((icon,i)=>`<span class="${i<at||done&&m.status==='completed'?'done':''} ${Math.abs(i-at)<.6&&!done?'here':''}">${icon}<small>${['ทางเข้า','ห้อง 1','ห้อง 2','บอส'][i]}</small></span>`).join('<i></i>')}</div>`;})()}<div class="section-title">${ongoing?'ความคืบหน้าการเดินทาง':m.status==='completed'?'ทีมกลับถึงบ้านแล้ว':m.status==='recalled'?'เรียกทีมกลับแล้ว':'ทีมถอยกลับมาพัก'}<small>${n(missionRatio(m)*100)}%</small></div><div class="progress"><i style="width:${pct(missionRatio(m),1)}%"></i></div>${missionEventPending(m)?`<div class="event-card" style="margin-top:15px"><h3>${h(m.event.title)}</h3><p>${h(m.event.text)}</p>${m.event.choices.map(c=>`<button data-event-choice="${h(c.id)}" data-mission="${h(m.id)}">${h(c.label)}<small>${h(c.description||'')}</small></button>`).join('')}</div>`:`<p class="detail-copy">${h(ongoing?(m.phase==='battle'?`พบ${q?.enemy} · การเตรียมทีมและอุปกรณ์มีผลกับการต่อสู้`:'สมาชิกกำลังสำรวจเส้นทาง คุณกลับไปจัดกิลด์ระหว่างรอได้'):(m.result?.message||'บันทึกการเดินทางอยู่ในสมุดกิลด์'))}</p>`}${ongoing?`<button class="secondary full-button" data-recall="${h(m.id)}">เรียกทีมกลับก่อน</button><p class="tiny-note">หยุดความเสี่ยงและกลับมาพัก เสบียงที่ใช้ไปไม่คืน และยังไม่ได้รางวัลคำร้อง</p>`:''}`;}
function renderMembers(){const stats=getGuildStats(state);if(ui.memberId)return renderMemberDetail();const recruits=getAvailableRecruits(state);return `<p class="panel-intro">สมาชิก ${stats.memberCount}/${stats.memberCap} คน · บ้านที่ทุกคนมีที่พัก<br>ฝึก พัก หรือช่วยงาน เลือกตารางให้เหมาะกับทีม</p>${state.members.map(m=>`<button class="member-card" data-member="${h(m.id)}">${portrait(m)}<div class="member-data"><b>${h(m.name)}</b><small>${h(jobName(m.class))} · Lv.${m.level} · ${h(taskText(m))}</small><div class="progress"><i style="width:${pct(m.energy)}%"></i></div></div><span class="member-tag">${n(m.energy)} / 100</span></button>`).join('')}<div class="section-title">ผู้สมัครเข้ากิลด์<small>ชื่อเสียงช่วยให้คนใหม่รู้จักเรา</small></div>${recruits.length?recruits.map(m=>`<div class="recruit-card"><div class="recruit-card-top">${portrait(m)}<div><b>${h(m.name)}</b><small>${h(jobName(m.class))} · ${h(m.trait)}</small></div></div><p class="tiny-note">${h(m.description)}</p><button data-recruit="${h(m.id)}" ${!m.available?'disabled':''}>${m.available?'รับเข้ากิลด์ · '+n(m.cost)+' G':h(m.reason||'ยังไม่เปิดรับ')}</button></div>`).join(''):'<p class="tiny-note">สมาชิกทุกคนเข้ากิลด์แล้ว</p>'}`;}
function renderMemberDetail(){const m=state.members.find(m=>m.id===ui.memberId);if(!m){ui.memberId=null;return renderMembers();}const def=MEMBERS.find(x=>x.id===m.id),stats=getMemberStats(state,m);const bondList=Object.entries(state.bonds||{}).filter(([key])=>key.split('|').includes(m.id)||key.split(':').includes(m.id)||key.split('-').includes(m.id));const next=JOBS[m.class]?.next||[];return `<button class="back-button" data-back>‹ สมาชิกกิลด์</button><div class="member-hero">${portrait(m)}<div><h2>${h(m.name)}</h2><p>${h(jobName(m.class))} · Lv.${m.level}</p><p>${h(taskText(m))}</p>${stats.waitingReason?'<p>'+h(stats.waitingReason)+'</p>':''}</div></div><div class="trait">${h(def?.trait||m.trait)} · ${h(def?.description||m.description)}</div><div class="stat-grid"><div class="stat-box">พลังต่อสู้<b>${n(stats.power)}</b></div><div class="stat-box">พลังพร้อมออกงาน<b>${n(m.energy)} / 100</b></div><div class="stat-box">ขวัญกำลังใจ<b>${n(m.morale)} / 100</b></div><div class="stat-box">ความคืบหน้าเลเวล<b>${n(m.xp)} XP</b></div></div>${m.injury>0?`<div class="inline-tip">กำลังรักษาบาดเจ็บ · อาการบาดเจ็บ ${n(m.injury)}/100</div>`:''}<div class="section-title">ตารางที่กิลด์</div><div class="segmented">${[['rest','พักฟื้น'],['train','ฝึกฝน'],['work','ช่วยงาน']].map(([id,label])=>`<button data-task="${id}" data-member-id="${h(m.id)}" class="${m.task===id?'active':''}" ${isAway(m.id)?'disabled':''}>${label}</button>`).join('')}</div><p class="tiny-note">ฝึกใช้พลังและเพิ่ม XP · ช่วยงานได้ไม้และสมุนไพร · เมื่อเหนื่อยจะพักก่อน</p><div class="section-title">อุปกรณ์ประจำตัว</div>${['weapon','accessory'].map(slot=>{const e=item(m.equipment?.[slot]);return`<div class="equipment-row">${e?itemIcon(e.id):'<span class="build-icon" style="width:28px;height:28px;font-size:14px">'+(slot==='weapon'?'⚔':'✧')+'</span>'}<span>${h(e?.name||(slot==='weapon'?'ยังไม่มีอาวุธ':'ยังไม่มีเครื่องราง'))}<small>${e?'พลัง +'+e.power:(slot==='weapon'?'อาวุธ':'เครื่องประดับ')}</small></span>${e?`<button data-unequip="${slot}" data-member-id="${h(m.id)}" ${isAway(m.id)?'disabled':''} style="font-size:9px;padding:3px 6px">ถอด</button>`:''}</div>`;}).join('')}<button class="secondary full-button" data-tab="workshop">คราฟต์และเลือกอุปกรณ์ →</button>${next.length?`<div class="section-title">เลือกสายเชี่ยวชาญ<small>Lv.5 และกิลด์ D</small></div>${next.map(id=>`<button class="build-card" data-specialize="${id}" data-member-id="${h(m.id)}" ${m.level<5||!rankEnough('D')||isAway(m.id)?'disabled':''}><span class="build-icon">${h(JOBS[id].icon)}</span><div class="build-info"><b>${h(JOBS[id].name)}</b><p>บทบาท${h(roleName(JOBS[id].role))} · พลังพื้นฐาน ${JOBS[id].power}</p></div></button>`).join('')}`:''}${bondList.length?`<div class="section-title">เพื่อนร่วมทาง</div>${bondList.slice(0,5).map(([key,value])=>{const ids=key.split(/[|:\-]/);const names=ids.map(id=>state.members.find(x=>x.id===id)?.name||id);return`<div class="bond-row">${h(names.join(' & '))}<span>ความไว้ใจ ${n(typeof value==='number'?value:value.value||value.level||0)}</span></div>`;}).join('')}`:''}`;}
function renderRoomDetail(room){
 const size=partitionSize(room),inside=state.facilities.filter(f=>containsRect(partitionRect(room),{...f,...getRoomSize(f.type,f.rotation||0)}));
 return `<button class="back-button" data-back>‹ ห้องและต่อเติม</button><h2 class="detail-title">${h(ROOM_TYPES[room.type].name)}</h2><p class="detail-copy">${size.w} × ${size.h} ช่อง · ของภายใน ${inside.length} ชิ้น</p><div class="facility-actions"><button data-move-room="${h(room.id)}">ย้ายทั้งห้อง</button><button data-rotate-room="${h(room.id)}">หมุนทั้งห้อง 90°</button></div><p class="tiny-note">ย้ายและหมุนพร้อมของภายใน ต้องเว้นทางเดินผ่านประตู</p><div class="room-size"><label>กว้าง<input aria-label="ปรับความกว้างห้อง" data-partition-size="width" type="number" min="2" max="14" step="1" value="${ui.roomDraftW??room.width}"></label><label>ลึก<input aria-label="ปรับความลึกห้อง" data-partition-size="height" type="number" min="2" max="14" step="1" value="${ui.roomDraftH??room.height}"></label></div><button class="primary full-button" data-resize-room="${h(room.id)}">ปรับขนาดห้อง</button><p class="tiny-note">เพิ่มขนาดใช้วัสดุตามพื้นที่ ลดขนาดได้เมื่อของภายในยังพอดี</p><div class="section-title">ของภายในห้อง</div>${inside.map(f=>`<button class="facility-row" data-facility="${h(f.id)}"><span>${h(FACILITIES[f.type].name)}</span><span>Lv.${f.level} →</span></button>`).join('')||'<p class="tiny-note">ห้องว่าง เลือกของจากเมนูแล้ววางภายในได้</p>'}<button class="danger full-button" data-demolish-room="${h(room.id)}">รื้อผนังห้อง</button><p class="tiny-note">ของภายในยังอยู่บนพื้นที่โล่ง</p>`;
}
function renderAreaStages(){const b=state.building,next=BUILDING_STAGES[b.level+1];return `<div class="expansion-card"><b>พื้นที่อาคาร ${b.width} × ${b.height}</b><p>ต่อเติมพื้นโล่งทีละขั้น แล้วเลือกสร้างห้องเอง</p><div class="area-stages">${BUILDING_STAGES.map((stage,i)=>`<div class="area-stage ${i===b.level?'current':''}"><span>${h(stage.name)}<small>${stage.width} × ${stage.height} ช่อง</small></span><b>${i<=b.level?'เปิดแล้ว':i===b.level+1&&rankEnough(stage.rank)?'ขั้นถัดไป':'กิลด์ '+stage.rank}</b></div>`).join('')}</div>${next?`<p class="build-cost">${h(moneyCost(getBuildingExpansionCost(state)))}</p><button class="primary" data-expand-building ${!rankEnough(next.rank)||!canAfford(getBuildingExpansionCost(state))?'disabled':''}>${rankEnough(next.rank)?'เปิดพื้นที่ขั้น '+(b.level+1)+' →':'ต้องมีกิลด์ '+next.rank}</button>`:'<p class="tiny-note">เปิดพื้นที่อาคารครบทุกขั้นแล้ว</p>'}</div>`;}
function renderRoomBuilder(){return `<div class="section-title">สร้างห้องบนพื้นที่โล่ง</div><p class="tiny-note">กำหนดขนาด เลือกชนิด แล้วแตะพื้นเพื่อวาง ประตูหมุนตามทิศห้อง จัดของแยกชิ้นภายในได้</p><div class="room-size"><label>กว้าง<input id="room-width" aria-label="ความกว้างห้องใหม่" data-room-dimension="width" type="number" min="2" max="14" step="1" value="${ui.roomWidth}"></label><label>ลึก<input id="room-height" aria-label="ความลึกห้องใหม่" data-room-dimension="height" type="number" min="2" max="14" step="1" value="${ui.roomHeight}"></label></div><p id="room-estimate" class="build-cost">${h(moneyCost(getPartitionCost(ui.roomWidth,ui.roomHeight)))}</p><div class="room-catalog">${Object.entries(ROOM_TYPES).map(([type,r])=>`<button data-room-type="${type}"><span style="background:${r.color}"></span>${h(r.name)}</button>`).join('')}</div>${state.rooms.length?`<div class="section-title">ห้องที่วางแล้ว</div>${state.rooms.map(room=>{const d=partitionSize(room);return `<button class="facility-row" data-partition="${h(room.id)}"><span>${h(ROOM_TYPES[room.type].name)}</span><span>${d.w}×${d.h} →</span></button>`;}).join('')}`:''}<div class="section-title">จัดของบนพื้นหรือภายในห้อง</div>`;}
function renderBuild(){
 const faces=['↘','↙','↖','↗'];
 if(ui.partitionId){const room=state.rooms.find(r=>r.id===ui.partitionId);if(room)return renderRoomDetail(room);}
 if(ui.facilityId){const f=state.facilities.find(f=>f.id===ui.facilityId);if(f){const d=FACILITIES[f.type],size=getRoomSize(f.type,f.rotation||0);return `<button class="back-button" data-back>‹ ห้องและต่อเติม</button><h2 class="detail-title">${h(d.name)}</h2><p class="detail-copy">${h(d.description)}</p><div class="stat-grid"><div class="stat-box">ระดับ<b>${f.level} / 3</b></div><div class="stat-box">พื้นที่ / ทิศ<b>${size.w} × ${size.h} ${faces[f.rotation||0]}</b></div></div><button class="primary full-button" data-upgrade="${h(f.id)}" ${f.level>=3?'disabled':''}>อัปเกรด</button><p class="tiny-note">${h(moneyCost(getUpgradeCost(state,f.id)))}</p><div class="facility-actions"><button data-move="${h(f.id)}">ย้าย / จัดวาง</button><button data-rotate="${h(f.id)}">หมุน 90°</button><button class="danger" data-demolish="${h(f.id)}">เก็บออก</button></div><div class="inline-tip">จัดวางทีละหนึ่งในสี่ช่อง เว้นทางเข้ากับด้านใช้งานของแต่ละชิ้น</div>`;}}
 const tab=ui.buildTab||'items',tabs=`<div class="sheet-tabs">${[['items','ของในบ้าน'],['rooms','ห้อง'],['expand','ต่อเติม']].map(([id,label])=>`<button data-build-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div>`;
 if(tab==='rooms')return tabs+renderRoomBuilder().replace('<div class="section-title">จัดของบนพื้นหรือภายในห้อง</div>','');
 if(tab==='expand')return tabs+renderAreaStages()+`<div class="expansion-card"><b>ที่ดิน ${state.grid.width}×${state.grid.height}</b><p>ซื้อที่ดินรอบกิลด์เพิ่ม วางแปลงสมุนไพรกลางแจ้งได้</p><p class="build-cost">${h(moneyCost(getExpansionCost(state)))}</p><button data-expand ${state.landLevel>=2||!rankEnough(state.landLevel===0?'E':'C')||!canAfford(getExpansionCost(state))?'disabled':''}>ซื้อที่ดินเพิ่ม →</button></div>`;
 return tabs+`<p class="tiny-note">แตะของที่อยากได้ แล้วแตะพื้นในบ้านเพื่อวาง</p><div class="shop-grid">${Object.entries(FACILITIES).map(([type,f])=>{const locked=!rankEnough(f.unlockRank),unique=['reception','dispatch'].includes(type)&&state.facilities.some(o=>o.type===type),afford=canAfford(f.cost),owned=state.facilities.filter(o=>o.type===type).length;return `<button class="shop-card ${locked?'locked':''}" data-build="${type}" ${locked||unique||!afford?'disabled':''}><canvas class="shop-art" width="128" height="88" data-furniture="${type}"></canvas><b>${h(f.name)}</b><small>${h(f.description)}</small><span class="shop-cost ${afford?'':'short'}">${h(moneyCost(f.cost))}</span>${locked?`<i class="shop-tag lock">กิลด์ ${h(f.unlockRank)}</i>`:unique?'<i class="shop-tag">วางแล้ว</i>':owned?`<i class="shop-tag">มี ${owned}</i>`:''}</button>`;}).join('')}</div><div class="section-title">ของที่วางอยู่</div>${state.facilities.map(f=>`<button class="facility-row" data-facility="${h(f.id)}"><span>${h(FACILITIES[f.type].name)}</span><span>Lv.${f.level} ${faces[f.rotation||0]} →</span></button>`).join('')}`;
}

function renderWorkshop(){const maxWorkshop=Math.max(0,...state.facilities.filter(f=>f.type==='workshop').map(f=>f.level));return `<p class="panel-intro">ของจากการเดินทาง กลายเป็นอุปกรณ์ชิ้นใหม่<br>คราฟต์ก่อน แล้วเลือกสมาชิกเพื่อสวมใส่</p>${EQUIPMENT.map(e=>{const eligible=state.members.filter(m=>!isAway(m.id)&&(!e.classes.length||e.classes.includes(baseJob(m.class))));const count=availableCount(e.id);const locked=!rankEnough(e.unlockRank)||maxWorkshop<e.workshopLevel;return `<div class="item-card"><div class="item-top">${itemIcon(e.id)}<div><b>${h(e.name)}</b><small>${e.slot==='weapon'?'อาวุธ':'เครื่องราง'} · พลัง +${e.power} · ในคลัง ${count}</small></div></div><p>${h(e.description)}${e.classes.length?' · '+e.classes.map(jobName).join('/'):' · ทุกอาชีพ'}</p><div class="build-cost">${h(moneyCost(e.cost))}</div><div class="item-actions" style="margin-top:8px"><button class="${locked?'secondary':'primary'}" data-craft="${e.id}" ${locked||!canAfford(e.cost)?'disabled':''}>${locked?'ต้องการกิลด์ '+e.unlockRank+' / โต๊ะช่าง '+e.workshopLevel:'คราฟต์'}</button>${count>0&&eligible.length?`<select aria-label="สมาชิกที่สวม ${h(e.name)}" data-equip-select="${e.id}">${eligible.map(m=>`<option value="${h(m.id)}">${h(m.name)}</option>`).join('')}</select><button data-equip="${e.id}">ใส่</button>`:''}</div></div>`;}).join('')}`;}
function renderJournal(){const stats=getGuildStats(state);const nextRequirement=RANK_REQUIREMENTS[stats.nextRank];const nextQuest=QUESTS.find(q=>q.id===nextRequirement?.quest);let goals=state.story?.finished?['ช่วยทีมสำรวจกลับบ้าน','รักษาหัวใจป่า','มีบ้านให้ทุกคนกลับมา']:[stats.nextRank?`ชื่อเสียง ${n(state.rep)} / ${n(nextRequirement?.rep||0)}`:'กิลด์ระดับ A',nextQuest?`สำเร็จคำร้อง ${nextQuest.name}`:'สำเร็จคำร้องรักษาหัวใจป่า'];const ledger=(state.ledger||[]).slice(0,8);return `${state.story?.finished?'<div class="finished-banner"><b>ทุกคนกลับบ้านแล้ว ❧</b><br>กิลด์ใบอ่อนคืนแสงให้ป่าได้สำเร็จ ขอบคุณที่ดูแลนักผจญภัยทุกคน คุณเล่นต่อ รับคนใหม่ และตกแต่งกิลด์ได้</div>':''}<div class="chapter-card"><small>OUR GUILD STORY · CHAPTER ${state.story?.chapter||1}</small><h2>${state.story?.finished?'บ้านใต้ร่มใบไม้':stats.nextRank?'ก้าวต่อไป · กิลด์ระดับ '+stats.nextRank:'รักษาหัวใจป่า'}</h2><p>จากบ้านเล็กท้ายเมือง สู่สถานที่ที่ผู้คนฝากความหวัง</p><ul>${goals.map(goal=>`<li>${h(goal)}</li>`).join('')}</ul><div class="progress"><i style="width:${pct(stats.rankProgress,1)}%"></i></div></div><div class="stat-grid"><div class="stat-box">คำร้องที่สำเร็จ<b>${n(Object.values(state.completedQuests||{}).reduce((s,v)=>s+Number(v||0),0))} งาน</b></div><div class="stat-box">ค่าดูแลต่อวัน<b>${n(stats.upkeep)} G</b></div><div class="stat-box">รายรับวันนี้<b>${n(stats.incomeToday)} G</b></div><div class="stat-box">รายจ่ายวันนี้<b>${n(stats.expenseToday)} G</b></div></div><div class="section-title">ช่วงเวลาดี ๆ ในกิลด์</div>${GUILD_EVENTS.map(e=>`<div class="item-card"><b style="font-size:12px">${h(e.name)}</b><p>${h(e.description)}</p><div class="build-cost">${h(moneyCost(e.cost))}</div><button class="secondary full-button" data-host-event="${e.id}" ${!state.facilities.some(f=>f.type===e.requires)||!canAfford(e.cost)?'disabled':''}>${state.facilities.some(f=>f.type===e.requires)?'จัดกิจกรรม':'ต้องมี'+FACILITIES[e.requires].name}</button></div>`).join('')}<div class="section-title">บัญชีล่าสุด</div>${ledger.length?ledger.map(entry=>{const amount=Number(entry.amount||entry.gold||0);return`<div class="ledger-row"><span>${h(entry.label||entry.text||entry.reason||entry.type)} · วันที่ ${entry.day}</span><b class="${amount<0?'negative':''}">${amount>0?'+':''}${n(amount)} G</b></div>`;}).join(''):'<p class="tiny-note">เริ่มรับคำร้องเพื่อเพิ่มรายรับของกิลด์</p>'}<div class="section-title">เรื่องราวที่เกิดขึ้น</div>${(state.log||[]).slice(0,14).map(entry=>`<div class="log-entry"><small>วันที่ ${h(entry.day)} · GUILD MEMORY</small>${h(entry.text)}</div>`).join('')}`;}
function navigate(tab){ui.partitionId=null;ui.roomDraftW=null;ui.roomDraftH=null;ui.tab=tab;openMenu();ui.questId=null;ui.memberId=null;ui.facilityId=null;ui.missionId=null;ui.selected.clear();syncUI();$('panel-content').scrollTop=0;}
function cancelBuild(){ui.buildType=null;ui.moveId=null;ui.roomPlacement=null;ui.moveRoomId=null;renderer?.setRoomMode(null);renderer?.setBuildMode(null);renderer?.setMoveMode(null);syncHUD();}
function onSceneSelect(selection){if(selection.kind==='pickup'){const f=state.facilities.find(f=>f.id===selection.id);if(!f)return;closeMenu();ui.buildType=null;ui.roomPlacement=null;ui.moveRoomId=null;ui.facilityId=null;ui.moveId=f.id;syncHUD();return;}if(selection.kind==='member'&&selection.id==='master'){cancelBuild();openSetup('edit');return;}if(selection.kind==='room'&&ui.roomPlacement){if(dispatch('buildRoom',{...ui.roomPlacement,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='moveRoom'&&ui.moveRoomId){if(dispatch('moveRoom',{roomId:ui.moveRoomId,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='partition'){cancelBuild();navigate('build');ui.partitionId=selection.id;syncUI();}else if(selection.kind==='build'&&ui.buildType){if(dispatch('build',{type:ui.buildType,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='move'&&ui.moveId){if(dispatch('move',{facilityId:ui.moveId,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='member'){cancelBuild();navigate('members');ui.memberId=selection.id;syncUI();}else if(selection.kind==='facility'){cancelBuild();navigate('build');ui.facilityId=selection.id;syncUI();}}
let confirmCallback;
function confirmAction(title,message,callback){$('confirm-title').textContent=title;$('confirm-message').textContent=message;confirmCallback=callback;$('confirm-dialog').showModal();}
$('confirm-cancel').addEventListener('click',()=>{$('confirm-dialog').close();confirmCallback=null;});$('confirm-ok').addEventListener('click',()=>{$('confirm-dialog').close();const callback=confirmCallback;confirmCallback=null;callback?.();});
function openSettings(){$('management-dialog').close();$('settings-content').innerHTML=`<h2>บ้านหลังนี้ บันทึกไว้ได้</h2><p>เซฟอยู่ในเบราว์เซอร์ของเครื่องนี้ ส่งออกไฟล์เพื่อสำรองหรือย้ายไปเครื่องอื่นได้</p>${saveFailure?`<div class="save-warning">${h(saveFailure)}</div>`:''}<div class="settings-row"><button class="primary" data-save-now>บันทึกตอนนี้</button><button data-export-save>ส่งออกเซฟ</button><button data-import-save>นำเข้าเซฟ</button></div><div class="settings-divider"></div><h3>เสียงและการควบคุม</h3><div class="settings-row"><button data-toggle-sound>${ui.sound?'♪ เสียงเปิด':'♪ เสียงปิด'}</button></div><p>ลากฉากเพื่อเลื่อน · ใช้ + / − หรือสองนิ้วเพื่อซูม<br>กดพื้นห้องเพื่อย้าย/หมุนทั้งห้อง · กดของเพื่อจัดวาง/อัปเกรด · กดคนเพื่อดูรายละเอียด<br>Space หยุดเวลา · 1 / 2 / 4 เร่งเวลา · R หมุน · Esc ยกเลิกการวาง</p><div class="settings-divider"></div><h3>เริ่มการเดินทางใหม่</h3><p>เริ่มกิลด์ใหม่จะเขียนทับเซฟของเครื่องนี้ ส่งออกเซฟเดิมไว้ก่อนหากต้องการเก็บ</p><button class="danger" data-new-game>เริ่มกิลด์ใหม่</button><p class="tiny-note">เวอร์ชันแรกที่เล่นได้ · ความยาวแคมเปญยังอยู่ระหว่างปรับสมดุล</p>`;$('settings-dialog').showModal();}
$('settings-button').addEventListener('click',openSettings);
$('import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>2000000){toast('ไฟล์เซฟใหญ่เกินไป',true);return;}try{const imported=deserializeGame(await file.text());$('settings-dialog').close();confirmAction('ใช้เซฟจากไฟล์นี้?',`กิลด์ระดับ ${imported.rank} วันที่ ${imported.day} · ข้อมูลปัจจุบันจะถูกแทนที่`,()=>{state=imported;state.settings.paused=false;ui={...ui,tab:'quests',region:'meadow',questId:null,memberId:null,missionId:null,facilityId:null,selected:new Set(),paused:false,speed:state.settings.speed||1,sound:!!state.settings.sound,tutorial:!state.completedQuests?.patrol};cancelBuild();renderer?.setState(state);renderer?.resetView?.();seenLog=state.log[0];save();syncUI();toast('นำเข้ากิลด์เรียบร้อย');});}catch(error){toast('ไฟล์เซฟไม่ถูกต้องหรือไม่รองรับ ข้อมูลปัจจุบันยังอยู่',true);}});
document.addEventListener('click',event=>{const b=event.target.closest('button,[role="button"]');if(!b||b.disabled)return;const d=b.dataset;if(d.tab){navigate(d.tab);return;}if(d.region){ui.region=d.region;syncUI();return;}if(d.quest){ui.questId=d.quest;ui.missionId=null;ui.selected.clear();syncUI();return;}if(d.member){ui.memberId=d.member;ui.tab='members';syncUI();return;}if(d.facility){ui.partitionId=null;ui.facilityId=d.facility;ui.tab='build';syncUI();return;}if(d.openMission){openMenu();ui.tab='quests';ui.missionId=d.openMission;ui.questId=null;syncUI();return;}if('back'in d){ui.partitionId=null;ui.roomDraftW=null;ui.roomDraftH=null;ui.questId=null;ui.memberId=null;ui.facilityId=null;ui.missionId=null;ui.selected.clear();syncUI();return;}if(d.pickMember){if(ui.selected.has(d.pickMember))ui.selected.delete(d.pickMember);else if(ui.selected.size<3)ui.selected.add(d.pickMember);else toast('หนึ่งทีมจัดได้ไม่เกินสามคน',true);syncUI();return;}if(d.policy){ui.policy=d.policy;syncUI();return;}if('sendMission'in d){if(dispatch('sendMission',{questId:ui.questId,memberIds:[...ui.selected],policy:ui.policy})){ui.missionId=activeMissions().at(-1)?.id;ui.questId=null;ui.selected.clear();syncUI();}return;}if(d.eventChoice){dispatch('chooseEvent',{missionId:d.mission,choiceId:d.eventChoice});return;}if(d.recall){confirmAction('เรียกทีมกลับ?', 'ทีมจะหยุดภารกิจและกลับมาพักที่กิลด์',()=>dispatch('recallMission',{missionId:d.recall}));return;}if(d.recruit){dispatch('recruit',{memberId:d.recruit});return;}if(d.task){dispatch('setTask',{memberId:d.memberId,task:d.task});return;}if(d.build){cancelBuild();ui.buildType=d.build;ui.moveId=null;ui.facilityId=null;renderer?.setMoveMode(null);renderer?.setBuildMode(d.build);closeMenu();syncUI();return;}if(d.roomType){if(!$('room-width').reportValidity()||!$('room-height').reportValidity())return;const room={type:d.roomType,width:Number($('room-width').value),height:Number($('room-height').value),rotation:0};cancelBuild();ui.facilityId=null;ui.partitionId=null;ui.roomPlacement=room;renderer?.setRoomMode(room);closeMenu();syncHUD();return;}if(d.partition){ui.facilityId=null;ui.partitionId=d.partition;ui.roomDraftW=null;ui.roomDraftH=null;ui.tab='build';syncUI();return;}if(d.moveRoom){const room=state.rooms.find(r=>r.id===d.moveRoom);cancelBuild();ui.moveRoomId=room.id;renderer?.setRoomMode(room,room.id);closeMenu();syncHUD();return;}if(d.rotateRoom){dispatch('rotateRoom',{roomId:d.rotateRoom});return;}if(d.resizeRoom){const inputs=[...document.querySelectorAll('[data-partition-size]')];if(inputs.some(i=>!i.reportValidity()))return;dispatch('resizeRoom',{roomId:d.resizeRoom,width:Number(inputs.find(i=>i.dataset.partitionSize==='width').value),height:Number(inputs.find(i=>i.dataset.partitionSize==='height').value)});return;}if(d.demolishRoom){confirmAction('รื้อผนังห้อง?', 'ของภายในจะอยู่บนพื้นที่โล่ง ได้วัสดุคืนบางส่วน',()=>{if(dispatch('demolishRoom',{roomId:d.demolishRoom})){ui.partitionId=null;syncUI();}});return;}if('cancelBuild'in d){cancelBuild();return;}if(d.rotate){dispatch('rotate',{facilityId:d.rotate});return;}if('rotatePlacement'in d){renderer?.rotatePlacement();syncHUD();return;}if('expandBuilding'in d){confirmAction('ต่อเติมอาคาร?',moneyCost(getBuildingExpansionCost(state)),()=>dispatch('expandBuilding'));return;}if(d.move){cancelBuild();ui.moveId=d.move;ui.buildType=null;renderer?.setBuildMode(null);renderer?.setMoveMode(d.move);closeMenu();syncHUD();return;}if(d.upgrade){const f=state.facilities.find(f=>f.id===d.upgrade);const def=FACILITIES[f.type];const cost=getUpgradeCost(state,f.id);confirmAction('อัปเกรด'+def.name,`ปรับปรุงเป็นระดับ ${f.level+1} · ${moneyCost(cost)}`,()=>dispatch('upgrade',{facilityId:d.upgrade}));return;}if(d.demolish){confirmAction('รื้อของชิ้นนี้?', 'พื้นที่จะว่างให้จัดวางใหม่ ได้ทรัพยากรคืนบางส่วน ความจุและโบนัสจะลดลง',()=>{if(dispatch('demolish',{facilityId:d.demolish})){ui.facilityId=null;syncUI();}});return;}if('expand'in d){confirmAction('ขยายที่ดินกิลด์?',`${state.grid.width+6}×${state.grid.height+4} ช่อง · ${moneyCost(getExpansionCost(state))}`,()=>dispatch('expand'));return;}if(d.craft){dispatch('craft',{equipmentId:d.craft});return;}if(d.equip){const select=document.querySelector(`[data-equip-select="${CSS.escape(d.equip)}"]`);if(select)dispatch('equip',{memberId:select.value,equipmentId:d.equip});return;}if(d.unequip){dispatch('equip',{memberId:d.memberId,equipmentId:null,slot:d.unequip});return;}if(d.specialize){confirmAction('เลือกสาย'+JOBS[d.specialize].name+'?', 'สมาชิกจะเชี่ยวชาญสายนี้ การเลือกสายเป็นการตัดสินใจถาวรของรอบเล่น',()=>dispatch('specialize',{memberId:d.memberId,classId:d.specialize}));return;}if(d.hostEvent){dispatch('hostEvent',{eventId:d.hostEvent});return;}if(d.speed){ui.speed=Number(d.speed);state.settings.speed=ui.speed;ui.paused=false;syncHUD();save();return;}if('dismissTutorial'in d){ui.tutorial=false;syncUI();return;}if('saveNow'in d){save(true);return;}if('exportSave'in d){const blob=new Blob([serializeGame(state)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`little-leaf-guild-day-${state.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ส่งออกไฟล์เซฟแล้ว');return;}if('importSave'in d){$('import-file').click();return;}if('toggleSound'in d){ui.sound=!ui.sound;state.settings.sound=ui.sound;save();playChime();b.textContent=ui.sound?'♪ เสียงเปิด':'♪ เสียงปิด';return;}if('newGame'in d){$('settings-dialog').close();confirmAction('เริ่มกิลด์ใหม่?', 'เซฟปัจจุบันจะถูกแทนที่ เริ่มจากบ้านว่างหลังแรก',()=>{closeMenu();showTitle();openSetup('new');});}});
$('pause-button').addEventListener('click',()=>{ui.paused=!ui.paused;syncHUD();});
$('zoom-in').addEventListener('click',()=>{ui.zoom=Math.min(2.4,(renderer?.zoom||1)+.15);renderer?.setZoom(ui.zoom);});$('zoom-out').addEventListener('click',()=>{ui.zoom=Math.max(.6,(renderer?.zoom||1)-.15);renderer?.setZoom(ui.zoom);});$('home-view').addEventListener('click',()=>{ui.zoom=1;renderer?.resetView?.();renderer?.setZoom(1);});
document.addEventListener('input',event=>{const d=event.target.dataset;if(d.roomDimension){ui[d.roomDimension==='width'?'roomWidth':'roomHeight']=Number(event.target.value);if($('room-estimate'))$('room-estimate').textContent=moneyCost(getPartitionCost(ui.roomWidth,ui.roomHeight));}if(d.partitionSize)ui[d.partitionSize==='width'?'roomDraftW':'roomDraftH']=Number(event.target.value);});
document.addEventListener('keydown',event=>{if(event.target.matches('input,select,textarea,button')||document.querySelector('dialog[open]'))return;if((event.key==='Enter'||event.key===' ')&&event.target.matches('[role="button"]')){event.preventDefault();event.target.click();return;}if(event.code==='KeyR'&&(ui.buildType||ui.moveId||ui.roomPlacement||ui.moveRoomId)){event.preventDefault();renderer?.rotatePlacement();syncHUD();return;}if(event.code==='Space'){event.preventDefault();ui.paused=!ui.paused;syncHUD();}if(['1','2','4'].includes(event.key)){ui.speed=Number(event.key);state.settings.speed=ui.speed;ui.paused=false;syncHUD();save();}if(event.key==='Escape'){cancelBuild();closeMenu();}});

// Goal card: always says what to do next, and opens the screen that does it.
function introGoal(){const step=state.intro.step,cost=type=>moneyCost(FACILITIES[type].cost);
 if(step==='reception')return{label:'บทนำ 1/5',title:'วางโต๊ะรับคำร้อง',meta:`ที่รับงานจากชาวบ้าน · แตะที่นี่แล้วแตะพื้นในบ้าน · ${cost('reception')}`,action:'build:reception',urgent:true};
 if(step==='dorm')return{label:'บทนำ 2/5',title:'วางเตียงพัก',meta:`นักผจญภัยจะอยู่ได้ต้องมีที่นอน · ${cost('dorm')}`,action:'build:dorm',urgent:true};
 if(step==='training')return{label:'บทนำ 3/5',title:'วางหุ่นฝึก',meta:`ให้มิราฝึกฝีมือ แล้วข่าวจะไปถึงคนอื่น · ${cost('training')}`,action:'build:training',urgent:true};
 if(step==='wait')return{label:'บทนำ',title:'รอคนมาเคาะประตู…',meta:'ข่าวว่ากิลด์เปิดแล้วกำลังแพร่ไปในหมู่บ้าน',progress:Math.min(1,state.intro.timer/(state.intro.delay||6)),action:'none'};
 if(step==='visit')return{label:'ก๊อก ก๊อก',title:'มีคนมาเคาะประตูกิลด์!',meta:'แตะเพื่อออกไปต้อนรับ',action:'visit',urgent:true};
 return null;}
function goalInfo(){if(introActive(state)){const g=introGoal();if(g)return g;}const stats=getGuildStats(state),missions=activeMissions(),pending=missions.find(m=>missionEventPending(m));
 if(pending)return{label:'ตัดสินใจ',title:'ทีมเจอเหตุการณ์ระหว่างทาง',meta:'แตะเพื่อเลือกว่าทีมจะทำอย่างไร',action:'mission:'+pending.id,urgent:true};
 if(!state.completedQuests?.patrol){const m=missions.find(m=>m.questId==='patrol');
  if(m)return{label:'กำลังเดินทาง',title:'รอทีมลาดตระเวนกลับบ้าน',meta:`อีก ${Math.max(0,Math.ceil(m.duration-m.progress))} วินาที · กด ×4 เพื่อเร่งเวลา`,progress:missionRatio(m),action:'mission:'+m.id};
  if(missions.length)return{label:'กำลังเดินทาง',title:'รอทีมกลับบ้าน',meta:'แตะเพื่อดูทีม',progress:missionRatio(missions[0]),action:'mission:'+missions[0].id};
  return{label:introActive(state)?'บทนำ 4/5':'เริ่มที่นี่',title:'ส่งทีมลาดตระเวนครั้งแรก',meta:'แตะที่นี่ → เลือกสมาชิก 3 คน → ส่งทีม',action:'quest:patrol',urgent:true};}
 if(state.story?.finished)return{label:'จบฤดูกาลแรก',title:'บ้านที่ทุกคนได้กลับมา',meta:'รับคำร้องและพัฒนากิลด์ต่อได้',action:'quests'};
 if(state.rank!=='F'&&!state.facilities.some(f=>f.type==='dispatch'))return{label:'ปลดล็อกแล้ว',title:'วางโต๊ะวางแผน',meta:`ส่งได้สองทีมพร้อมกัน · ${moneyCost(FACILITIES.dispatch.cost)}`,action:'build'};
 if(!stats.nextRank)return{label:'บทสุดท้าย',title:'รักษาหัวใจป่า',meta:'รับคำร้องสุดท้ายที่ป่าหมอกจันทร์',action:'quest:heart'};
 const q=QUESTS.find(q=>q.id===stats.nextRankQuest),needQuest=q&&!state.completedQuests?.[q.id],open=needQuest&&getAvailableQuests(state).some(x=>x.id===q.id);
 const idle=missions.length?'':' · ทีมว่างอยู่ แตะเพื่อรับคำร้อง';
 return{label:'เป้าหมาย',title:`เลื่อนเป็นกิลด์ระดับ ${stats.nextRank}`,meta:`ชื่อเสียง ${n(state.rep)}/${n(stats.nextRankRep)}${needQuest?` · ต้องสำเร็จ “${q.name}”`:''}${idle}`,progress:Math.min(1,state.rep/Math.max(1,stats.nextRankRep)),action:open?'quest:'+q.id:'quests',urgent:!missions.length};}
function syncGoal(){const g=goalInfo(),card=$('goal-card');if(!card)return;const html=`<small>${h(g.label)}</small><b>${h(g.title)}</b><span>${h(g.meta)}</span>${g.progress!=null?`<i class="goal-progress"><i style="width:${pct(g.progress,1)}%"></i></i>`:''}`;if(card.__html!==html){card.innerHTML=html;card.__html=html;}card.dataset.goal=g.action;card.classList.toggle('urgent',!!g.urgent);}
function runGoal(action){const[kind,id]=String(action).split(':');if(kind==='none')return;if(kind==='visit'){showVisitors();return;}cancelBuild();
 if(kind==='build'&&id){closeMenu();ui.buildType=id;ui.moveId=null;ui.facilityId=null;renderer?.setMoveMode(null);renderer?.setBuildMode(id);syncUI();return;}
 if(kind==='quest'){navigate('quests');const q=QUESTS.find(q=>q.id===id);if(q){ui.region=q.region;ui.questId=id;}syncUI();return;}
 if(kind==='mission'){openMenu();ui.tab='quests';ui.missionId=id;ui.questId=null;syncUI();return;}
 navigate(kind==='build'?'build':'quests');}
$('goal-card').addEventListener('click',()=>runGoal($('goal-card').dataset.goal));

// Mission report: a clear payoff when a team comes home.
const reported=new Set(state.missions.filter(m=>m.status!=='active'&&m.status!=='decision').map(m=>m.id));const reportQueue=[];
function queueReports(before){for(const m of state.missions){if(reported.has(m.id)||m.status==='active'||m.status==='decision')continue;reported.add(m.id);reportQueue.push({mission:m,before,rank:state.rank});}if(reportQueue.length&&!$('report-dialog').open)showReport();}
function showReport(){const r=reportQueue.shift();if(!r)return;const m=r.mission,q=QUESTS.find(q=>q.id===m.questId),res=m.result||{},rw=res.reward||{};
 const chips=[['gold','◈','G'],['wood','▰','ไม้'],['stone','◆','หิน'],['herb','❧','สมุนไพร'],['rep','★','ชื่อเสียง']].filter(([k])=>rw[k]>0).map(([k,icon,label])=>`<span class="report-chip"><b>${icon} +${n(rw[k])}</b><small>${label}</small></span>`).join('');
 const xp=Math.round((q?.reward?.xp||0)*(res.success?1:.35)),team=m.memberIds.map(id=>state.members.find(x=>x.id===id)).filter(Boolean).map(x=>{const up=x.level>(r.before.levels.get(x.id)||x.level);return `<div class="report-member ${up?'up':''}">${portrait(x)}<b>${h(x.name)}</b><small>${up?'เลเวลอัป! Lv.'+x.level:'Lv.'+x.level} · +${n(xp)} XP${x.injury>0?' · บาดเจ็บ':''}</small></div>`;}).join('');
 let rank='';if(RANKS.indexOf(r.rank)>RANKS.indexOf(r.before.rank)){const unlocked=QUESTS.filter(x=>x.rank===r.rank).map(x=>x.name);if(r.rank==='E')unlocked.push('โต๊ะวางแผน (ส่งสองทีม)');rank=`<div class="report-rank"><span class="rank-seal">${h(r.rank)}</span><div><b>กิลด์เลื่อนเป็นระดับ ${h(r.rank)}!</b><small>${unlocked.length?'ปลดล็อก: '+h(unlocked.join(' · ')):'เปิดคำร้องและสิ่งปลูกสร้างใหม่'}</small></div></div>`;}
 const next=goalInfo();
 $('report-content').innerHTML=`<small class="report-kicker">${res.success?'ภารกิจสำเร็จ':'ทีมถอยกลับมา'} · ${h(q?.name||'')}</small><h2 id="report-title">${h(res.title||'ทีมกลับถึงบ้าน')}</h2><p>${h(res.message||'')}</p>${chips?`<div class="report-chips">${chips}</div>`:''}<div class="report-team">${team}</div>${rank}<div class="report-next"><small>ต่อไป</small><b>${h(next.title)}</b><span>${h(next.meta.replace(' · ทีมว่างอยู่ แตะเพื่อรับคำร้อง',''))}</span></div><div class="dialog-actions"><button class="secondary" data-report="close">กลับกิลด์</button><button class="primary" data-report="next">${next.action.startsWith('quest')||next.action==='quests'?'รับคำร้องต่อ':'ไปต่อ'}</button></div>`;
 injectIcons($('report-content'));$('report-dialog').showModal();}
$('report-dialog').addEventListener('click',event=>{const b=event.target.closest('[data-report]');if(!b)return;const go=b.dataset.report==='next';$('report-dialog').close();syncHUD();if(go)runGoal(goalInfo().action);});
$('report-dialog').addEventListener('close',()=>{lastFrame=performance.now();if(reportQueue.length)setTimeout(showReport,250);});

// Opening chapter: title screen, prologue and adventurers knocking at the door.
const VISITOR_LINES={get mira(){return `ได้ยินว่าบ้านข้างต้นโอ๊กเปิดเป็น${profile().guildName}แล้ว… คุณ${profile().masterName} ให้ฉันช่วยเฝ้าบ้านหลังนี้ได้ไหม`;},finn:'มิราเล่าว่ามีหุ่นฝึกแล้ว! ผมจำทางรอบหมู่บ้านได้หมดเลยนะ',lune:'ขอมาด้วยคนค่ะ อยากลองใช้เวทช่วยชาวบ้านดูบ้าง',noa:'ได้ยินว่าทีมแรกกลับมาอย่างปลอดภัย ถ้ามีใครบาดเจ็บ ฉันดูแลให้เองนะ'};
const VISITOR_NEXT={training:'ต่อไป: วางหุ่นฝึกให้มิราฝึกฝีมือ',patrol:'ครบ 3 คนแล้ว! ส่งทีมลาดตระเวนครั้งแรกได้เลย',done:'สมาชิกครบสี่คนแล้ว ลองวางเตียงรักษาให้โนอาดูแลคนเจ็บ (เมนู → ห้องและต่อเติม)'};
function showVisitors(){if(!state.intro||state.intro.step!=='visit'||$('visitor-dialog').open)return;const ids=state.intro.visitors,people=ids.map(id=>MEMBERS.find(m=>m.id===id)).filter(Boolean);if(!people.length)return;
 $('visitor-content').innerHTML=`<small class="report-kicker">ก๊อก ก๊อก · มีคนมาที่ประตูกิลด์</small><h2 id="visitor-title">${people.length>1?h(people.map(p=>p.name).join(' และ '))+' มาขอเข้าร่วม':h(people[0].name)+' มาขอเข้าร่วมกิลด์'}</h2><div class="visitor-list">${people.map(p=>`<div class="visitor-card">${portrait(p)}<div><b>${h(p.name)}</b><small>${h(jobName(p.class))} · ${h(p.trait||'')}</small><p>“${h(VISITOR_LINES[p.id]||p.description)}”</p><span>${h(p.description)}</span></div></div>`).join('')}</div><div class="report-next"><small>ต่อไป</small><span>${h(VISITOR_NEXT[state.intro.after]||'')}</span></div><div class="dialog-actions"><button class="primary" data-welcome>ต้อนรับเข้ากิลด์</button></div>`;
 injectIcons($('visitor-content'));$('visitor-dialog').showModal();}
$('visitor-dialog').addEventListener('cancel',event=>event.preventDefault());
$('visitor-dialog').addEventListener('click',event=>{if(!event.target.closest('[data-welcome]'))return;const ids=[...(state.intro?.visitors||[])];renderer?.arrive?.(ids);$('visitor-dialog').close();if(dispatch('welcomeVisitors')){renderer?.resetView?.();}lastFrame=performance.now();});
const story=()=>{const p=profile();return[['จดหมายจากผู้ใหญ่บ้าน',`ถึงคุณ${p.masterName}`,'บ้านไม้ข้างต้นโอ๊กใหญ่ว่างมานาน ชาวบ้านอยากให้มีคนช่วยดูแลเส้นทางและป่ารอบหมู่บ้าน ช่วยเปิดบ้านหลังนี้เป็นกิลด์นักผจญภัยให้หน่อยได้ไหม'],['บ้านที่ยังว่างเปล่า',`${p.guildName} ยังไม่มีอะไรเลย`,'ไม่มีโต๊ะ ไม่มีเตียง และยังไม่มีนักผจญภัยสักคน ผู้ใหญ่บ้านฝากทุนตั้งต้นไว้ให้ 1,200 G พร้อมไม้และหินจำนวนหนึ่ง'],['หน้าที่ของหัวหน้ากิลด์',`${p.masterName} หัวหน้ากิลด์คนใหม่`,'กด “สร้าง” ที่แถบด้านล่างเพื่อวางของในบ้าน ต้อนรับนักผจญภัยที่มาเคาะประตู ส่งทีมไปรับคำร้อง แล้วพาทุกคนกลับบ้านอย่างปลอดภัย เริ่มจากวางโต๊ะรับคำร้องกันก่อน']];};
function showStory(page=0){const STORY=story(),[kicker,title,text]=STORY[page],last=page===STORY.length-1;$('story-content').innerHTML=`<div class="story-dots">${STORY.map((_,i)=>`<i class="${i===page?'on':''}"></i>`).join('')}</div><small class="report-kicker">${h(kicker)}</small><h2 id="story-title">${h(title)}</h2><p>${h(text)}</p><div class="dialog-actions">${last?'':'<button class="secondary" data-story-skip>ข้าม</button>'}<button class="primary" data-story-next="${page+1}">${last?'เริ่มเปิดกิลด์':'ต่อไป'}</button></div>`;if(!$('story-dialog').open)$('story-dialog').showModal();}
$('story-dialog').addEventListener('cancel',event=>event.preventDefault());
$('story-dialog').addEventListener('click',event=>{const b=event.target.closest('[data-story-next],[data-story-skip]');if(!b)return;const next=Number(b.dataset.storyNext);if(b.dataset.storySkip===undefined&&next<story().length){showStory(next);return;}$('story-dialog').close();lastFrame=performance.now();syncHUD();});
function startNewGame(profileDraft){state=createGame(Date.now()%100000+1,{opening:true,profile:profileDraft});hasSave=true;ui={...ui,tab:'quests',questId:null,memberId:null,facilityId:null,missionId:null,selected:new Set(),tutorial:true,paused:false,speed:1,sound:!!state.settings.sound};reported.clear();reportQueue.length=0;seenLog=state.log[0];cancelBuild();closeMenu();renderer?.setState(state);renderer?.resetView?.();save();syncUI();hideTitle();showStory(0);}
function showTitle(){document.body.classList.add('on-title');$('title-screen').hidden=false;$('title-continue').hidden=!hasSave;if(hasSave){$('title-save').textContent=`${profile().guildName} · `+(introActive(state)?`บทนำ · วันที่ ${n(state.day)}`:`วันที่ ${n(state.day)} · ระดับ ${state.rank} · สมาชิก ${state.members.length} คน`);}$('title-new').classList.toggle('primary',!hasSave);}
function hideTitle(){document.body.classList.remove('on-title');$('title-screen').hidden=true;lastFrame=performance.now();}
$('title-continue').addEventListener('click',()=>{hideTitle();playChime();});
$('title-new').addEventListener('click',()=>{if(hasSave&&!(introActive(state)&&state.day===1&&!state.facilities.length)){confirmAction('เริ่มกิลด์ใหม่?','เซฟปัจจุบันจะถูกแทนที่ เริ่มจากบ้านว่างหลังแรก',()=>openSetup('new'));return;}openSetup('new');});

// Player identity: the guild master and the guild's name.
function profile(){return state.profile||DEFAULT_PROFILE;}
function masterSprite(p){return{id:'master',name:p.masterName,class:'master',hair:p.hair,outfit:p.outfit,skin:p.skin,hairStyle:p.hairStyle};}
function syncBrand(){const p=profile();if($('brand-name').textContent!==p.guildName)$('brand-name').textContent=p.guildName;const sub=state.profile?`หัวหน้ากิลด์ ${p.masterName}`:'LITTLE LEAF GUILD';if($('brand-sub').textContent!==sub)$('brand-sub').textContent=sub;const title=`${p.guildName} · R20`;if(document.title!==title)document.title=title;}
function guildTabs(){return `<div class="sheet-tabs"><button data-tab="home" class="${ui.tab==='home'?'active':''}">ภาพรวม</button><button data-tab="journal" class="${ui.tab==='journal'?'active':''}">บันทึก</button><button data-edit-profile>หัวหน้ากิลด์</button><button data-guild-settings>เซฟ / ตั้งค่า</button></div>`;}
const NAME_IDEAS=['กิลด์ใบอ่อน','กิลด์ดาวเหนือ','กิลด์ชาอุ่น','กิลด์ต้นโอ๊ก','กิลด์หิ่งห้อย','กิลด์ขนมปังกรอบ'];
const LOOK_ROWS=[['hair','สีผม'],['outfit','สีชุด'],['skin','สีผิว']];
let setup=null;
function openSetup(mode){setup={mode,page:0,...normalizeProfile(mode==='edit'?profile():{masterName:'',guildName:''})};if(mode==='new'){setup.masterName='';setup.guildName='';}renderSetup();if(!$('setup-dialog').open)$('setup-dialog').showModal();}
function renderSetup(){const edit=setup.mode==='edit',first=setup.page===0;
 const look=LOOK_ROWS.map(([key,label])=>`<div class="look-row"><span>${label}</span><div>${PROFILE_LOOKS[key].map(c=>`<button class="swatch ${setup[key]===c?'on':''}" data-look="${key}" data-value="${c}" style="background:${c}" aria-label="${label} ${c}"></button>`).join('')}</div></div>`).join('')+`<div class="look-row"><span>ทรงผม</span><div>${[['short','สั้น'],['long','ยาว']].map(([v,l])=>`<button class="pill ${setup.hairStyle===v?'on':''}" data-look="hairStyle" data-value="${v}">${l}</button>`).join('')}</div></div>`;
 $('setup-content').innerHTML=first?`<small class="report-kicker">${edit?'แก้ไขหัวหน้ากิลด์':'สร้างหัวหน้ากิลด์ · 1/2'}</small><h2 id="setup-title">${edit?'หน้าตาและชื่อของคุณ':'หัวหน้ากิลด์คนใหม่คือคุณ'}</h2><div class="setup-master"><div class="setup-stage"><canvas id="setup-preview" width="96" height="96"></canvas><b id="setup-preview-name"></b></div><div class="setup-fields"><label class="setup-label">ชื่อหัวหน้ากิลด์<input id="setup-master" maxlength="20" placeholder="เช่น อาริน" value="${h(setup.masterName)}"></label>${look}</div></div><div class="dialog-actions"><button class="secondary" data-setup="${edit?'close':'back'}">${edit?'ยกเลิก':'กลับ'}</button><button class="primary" data-setup="next">${edit?'ต่อไป':'ต่อไป →'}</button></div>`
 :`<small class="report-kicker">${edit?'แก้ไขกิลด์':'ตั้งชื่อกิลด์ · 2/2'}</small><h2 id="setup-title">ตั้งชื่อกิลด์ของคุณ</h2><div class="guild-sign"><img src="${h(document.querySelector('.brand img')?.src||'')}" alt=""><b id="setup-sign"></b><small id="setup-sign-sub"></small></div><label class="setup-label">ชื่อกิลด์<input id="setup-guild" maxlength="20" placeholder="เช่น กิลด์ใบอ่อน" value="${h(setup.guildName)}"></label><div class="name-ideas">${NAME_IDEAS.map(x=>`<button class="pill" data-name-idea="${h(x)}">${h(x)}</button>`).join('')}</div><div class="dialog-actions"><button class="secondary" data-setup="prev">← ย้อนกลับ</button><button class="primary" data-setup="done">${edit?'บันทึก':'เปิดกิลด์!'}</button></div>`;
 updateSetupPreview();}
function updateSetupPreview(){const p=normalizeProfile(setup);if($('setup-preview')){drawPortrait($('setup-preview'),masterSprite(p),96);$('setup-preview-name').textContent=setup.masterName.trim()||'(ยังไม่ตั้งชื่อ)';}if($('setup-sign')){$('setup-sign').textContent=setup.guildName.trim()||'ชื่อกิลด์';$('setup-sign-sub').textContent=`หัวหน้ากิลด์ ${p.masterName}`;}}
$('setup-dialog').addEventListener('input',event=>{if(event.target.id==='setup-master')setup.masterName=event.target.value;if(event.target.id==='setup-guild')setup.guildName=event.target.value;updateSetupPreview();});
$('setup-dialog').addEventListener('cancel',event=>{event.preventDefault();if(setup?.mode==='edit')$('setup-dialog').close();});
$('setup-dialog').addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.look){setup[d.look]=d.value;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));updateSetupPreview();return;}
 if(d.nameIdea){setup.guildName=d.nameIdea;$('setup-guild').value=d.nameIdea;updateSetupPreview();return;}
 if(d.setup==='back'){$('setup-dialog').close();return;}
 if(d.setup==='close'){$('setup-dialog').close();return;}
 if(d.setup==='next'){if(!setup.masterName.trim()){$('setup-master').focus();$('setup-master').classList.add('need');toast('ตั้งชื่อหัวหน้ากิลด์ก่อนนะ',true);return;}setup.page=1;renderSetup();return;}
 if(d.setup==='prev'){setup.page=0;renderSetup();return;}
 if(d.setup==='done'){if(!setup.guildName.trim()){$('setup-guild').focus();toast('ตั้งชื่อกิลด์ก่อนนะ',true);return;}const p=normalizeProfile(setup);$('setup-dialog').close();if(setup.mode==='edit'){dispatch('setProfile',p);return;}startNewGame(p);}});
document.addEventListener('click',event=>{const b=event.target.closest('[data-build-tab],[data-edit-profile],[data-guild-settings]');if(!b)return;if(b.dataset.buildTab){ui.buildTab=b.dataset.buildTab;syncUI();$('panel-content').scrollTop=0;return;}if('editProfile'in b.dataset){closeMenu();openSetup('edit');return;}if('guildSettings'in b.dataset)$('settings-button').click();});

// Dock: tapping the open section again closes the sheet; tapping the scene closes it too.
$('dock').addEventListener('click',event=>{const b=event.target.closest('[data-dock]');if(!b||!$('management-dialog').open)return;const group=ui.tab==='journal'?'home':ui.tab;if(b.dataset.dock===group&&!ui.questId&&!ui.memberId&&!ui.facilityId&&!ui.missionId&&!ui.partitionId){event.stopPropagation();closeMenu();}},true);
$('world-wrap').addEventListener('pointerdown',()=>{if($('management-dialog').open)closeMenu();},true);
$('management-dialog').addEventListener('close',()=>document.body.classList.remove('sheet-open'));

// Placement bar: live validity from the renderer; nothing is placed until the player confirms.
function updatePlacementBar(info){if(!info?.active)return;const status=$('pb-status'),text=info.ok?'ลากของเพื่อย้าย · แตะพื้นเพื่อย้ายไปตรงนั้น':(info.message||'วางตรงนี้ไม่ได้');if(status.textContent!==text)status.textContent=text;status.classList.toggle('bad',!info.ok);$('build-hint').querySelector('[data-confirm-placement]').disabled=!info.ok;}
if(renderer)renderer.onPlacement=updatePlacementBar;
document.addEventListener('click',event=>{if(!event.target.closest('[data-confirm-placement]'))return;const p=renderer?.getPlacement();if(!p?.active)return;if(!p.ok){toast(p.message||'วางตรงนี้ไม่ได้',true);return;}onSceneSelect({kind:p.kind,x:p.x,y:p.y,rotation:p.rotation,facilityId:p.facilityId,roomId:p.roomId});});
let lastFrame=performance.now(),uiTimer=0,saveTimer=0,seenLog=state.log[0];
function frame(now){state.settings.paused=ui.paused;const dt=Math.max(0,Math.min((now-lastFrame)/1000,.25));lastFrame=now;if(renderer?.ready&&!document.hidden&&!ui.paused&&!$('confirm-dialog').open&&!$('settings-dialog').open&&!$('report-dialog').open&&!$('visitor-dialog').open&&!$('story-dialog').open&&!$('setup-dialog').open&&$('title-screen').hidden){const before={rank:state.rank,levels:new Map(state.members.map(m=>[m.id,m.level]))};tick(state,dt*ui.speed);queueReports(before);if(state.intro?.step==='visit'&&!$('report-dialog').open&&!$('management-dialog').open)showVisitors();renderer?.setState(state);uiTimer+=dt;saveTimer+=dt;if(state.log[0]!==seenLog){const latest=state.log[0];if(latest?.type!=='daily'){toast(latest.text);playChime();}seenLog=state.log[0];}if(uiTimer>.9){syncHUD();if(!document.activeElement?.matches('input,select,textarea')&&(ui.missionId||ui.questId||ui.tab==='journal'||ui.tab==='members'||ui.tab==='build'||ui.tab==='workshop'))syncUI();uiTimer=0;}if(saveTimer>12){save();saveTimer=0;}}if(ui.missionId)drawMissionScene();requestAnimationFrame(frame);}
function drawMissionScene(){const canvas=$('mission-scene');if(!canvas||!ui.missionId)return;const mission=state.missions.find(m=>m.id===ui.missionId);const quest=QUESTS.find(q=>q.id===mission?.questId);if(mission&&quest)drawDungeonScene(canvas,mission,quest,state,{paused:ui.paused||document.hidden||!$('management-dialog').open,time:performance.now()/1000,eventPending:missionEventPending(mission)});}

syncUI();injectIcons($('dock'));if(hasSave)save();showTitle();requestAnimationFrame(frame);if(loadNotice)setTimeout(()=>toast(loadNotice,true),800);document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();if(document.hidden)save();});window.addEventListener('pagehide',()=>save());
// Read-only diagnostics, useful for reproducible bug reports without a cheat menu.
window.guildDebug={getState:()=>JSON.parse(serializeGame(state)),getScenePoint:(x,y)=>{const r=renderer.worldToScreen(x*32,y*32),b=$('guild-world').getBoundingClientRect();return{x:b.left+r.x*b.width/renderer.width,y:b.top+r.y*b.height/renderer.height};},getRendererInfo:()=>renderer?.getInfo(),getSnapshot:()=>({rank:state.rank,day:state.day,members:state.members.length,quests:state.completedQuests,finished:state.story?.finished})};
